/// <summary>
/// AVA_007513_TransferJournalsDepreciation
/// </summary>
public void init()
{
    next init();

    AssetParameters_ds.object(fieldNum(AssetParameters, AVACalculationDimensionValue)).registerOverrideMethod(methodStr(FormDataObject, lookup), formMethodStr(AssetParameters, AVAOverrideDimValueLookup), this);
}

/// <summary>
/// AVA_007513_TransferJournalsDepreciation
/// </summary>
/// <param name = "_formCtrl">FormStringControl</param>
public void AVAOverrideDimValueLookup(FormStringControl _formCtrl)
{
    FormStringControl   dimNameCtrl;
    Name                dimName;
    DimensionAttribute  dimensionAttribute;
    dimNameCtrl = this.control(this.controlId(formControlStr(AssetParameters, AVACalcDimAttributeName)));
    dimName = dimNameCtrl.valueStr();
    dimensionAttribute = DimensionAttribute::findByName(dimName);
    DimensionValueLookupHelper::lookupDimensionValues(dimensionAttribute, _formCtrl);

}
